CREATE COLUMN TABLE "TEST_AP"."OFIX" ("AbsEntry" INTEGER CS_INT NOT NULL , "SrcObjType" NVARCHAR(20), "SrcObjAbs" INTEGER CS_INT, "Canceled" NVARCHAR(1) DEFAULT 'N', "CancelDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."OFIX" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$SrcObjType$SrcObjAbs$','SrcObjType','SrcObjAbs'));
CREATE INDEX "OFIX_SECONDARY" ON "TEST_AP"."OFIX" ( "SrcObjType" ASC, "SrcObjAbs" ASC )